 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Find 3x3 ring centers.
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr in (r - 1, r, r + 1)
                for cc in (c - 1, c, c + 1)
                if (rr, cc) != (r, c)
            ):
                centers.append((r, c))

    # The 2s form parallel rails. Each ring projects to the other rails;
    # a projection is a full perpendicular ray with a three-cell side bar.
    vertical = sum(all(grid[r][c] == 2 for r in range(h)) for c in range(w))
    horizontal = sum(all(grid[r][c] == 2 for c in range(w)) for r in range(h))
    vertical_rails = [c for c in range(w) if all(grid[r][c] == 2 for r in range(h))]
    horizontal_rails = [r for r in range(h) if all(grid[r][c] == 2 for c in range(w))]

    def paint(r, c):
        if 0 <= r < h and 0 <= c < w and out[r][c] == 0:
            out[r][c] = 1

    if vertical_rails:
        for r, c in centers:
            for rail in vertical_rails:
                if rail == c:
                    continue
                for cc in range(w):
                    paint(r, cc)
                for rr in (r - 1, r + 1):
                    for cc in (rail - 1, rail, rail + 1):
                        paint(rr, cc)
    elif horizontal_rails:
        for r, c in centers:
            for rail in horizontal_rails:
                if rail == r:
                    continue
                for rr in range(h):
                    paint(rr, c)
                for cc in (c - 1, c + 1):
                    for rr in (rail - 1, rail, rail + 1):
                        paint(rr, cc)
    return out

if __name__ == '__main__':
    pass
