 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Detect all 3x3 markers: a 3 border with a 2 center.
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr in range(r - 1, r + 2)
                for cc in range(c - 1, c + 2)
                if (rr, cc) != (r, c)
            ):
                centers.append((r, c))

    # Rails are regularly repeated 2s. Markers occlude a few rail positions;
    # use long columns/rows rather than requiring every cell to be 2.
    vrails = [c for c in range(w) if sum(grid[r][c] == 2 for r in range(h)) >= h - 3]
    hrails = [r for r in range(h) if sum(grid[r][c] == 2 for c in range(w)) >= w - 3]

    def ink(r, c):
        if 0 <= r < h and 0 <= c < w and grid[r][c] == 0:
            out[r][c] = 1

    # A ring projects along its centerline. At each crossing with an orthogonal
    # rail, the beam is widened to a three-cell bar; 2/3 cells remain intact.
    if vrails:
        for r, c in centers:
            for x in range(w):
                ink(r, x)
            for rail in vrails:
                for rr in (r - 1, r + 1):
                    for cc in (rail - 1, rail, rail + 1):
                        ink(rr, cc)
