    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr in range(r - 1, r + 2)
                for cc in range(c - 1, c + 2)
                if (rr, cc) != (r, c)
            ):
                centers.append((r, c))

    # 2-rails run across a row or down a column. A ring can replace rail
    # cells with 3s, so allow a small number of interruptions.
    horizontal = [r for r in range(h) if sum(v == 2 for v in grid[r]) >= w // 2]
    vertical = [c for c in range(w) if sum(grid[r][c] == 2 for r in range(h)) >= h // 2]

    def paint(r, c):
        if 0 <= r < h and 0 <= c < w and grid[r][c] == 0:
            out[r][c] = 1

    for r, c in centers:
        on_horizontal = r in horizontal
        on_vertical = c in vertical
        # Rays leave the marker perpendicular to the rail it sits on.
        if on_horizontal and not on_vertical:
            # Vertical beam; each other horizontal rail gets a 3x3 flare.
            for rr in range(h):
                paint(rr, c)
            for rail in horizontal:
                if rail == r:
                    continue
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        paint(rail + dr, c + dc)
        elif on_vertical and not on_horizontal:
            # Horizontal beam; each other vertical rail gets a 3x3 flare.
            for cc in range(w):
