                for rr in range(r - 1, r + 2)
                for cc in range(c - 1, c + 2)
                if (rr, cc) != (r, c)
            ):
                centers.append((r, c))

    # Identify the repeated straight rails, allowing interruptions by a ring.
    horizontal = [r for r in range(h) if sum(v == 2 for v in grid[r]) >= w // 2]
    vertical = [c for c in range(w) if sum(grid[r][c] == 2 for r in range(h)) >= h // 2]

    def line(r, c, vertical_beam):
        if vertical_beam:
            for rr in range(h):
                if grid[rr][c] == 0:
                    out[rr][c] = 1
        else:
            for cc in range(w):
                if grid[r][cc] == 0:
                    out[r][cc] = 1

    def flare(r, c):
        # At crossings, color the 3x3 flare except its central rail cell;
        # keep any original 3 marker cells intact.
        for rr in range(r - 1, r + 2):
            for cc in range(c - 1, c + 2):
                if (rr, cc) == (r, c):
                    continue
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != 3:
                    out[rr][cc] = 1

    for r, c in centers:
        on_h = r in horizontal
        on_v = c in vertical
        if on_h and not on_v:
            # Marker is on a horizontal rail; project vertically.
            line(r, c, True)
            for rail in vertical:
                if rail != c:
                    flare(r, rail)
        elif on_v and not on_h:
            # Marker is on a vertical rail; project horizontally.
            line(r, c, False)
            for rail in horizontal:
                if rail != r:
                    flare(rail, c)
            # Crossing rails of the same orientation are the targets.
            for rail in vertical:
                if rail != c:
                    flare(r, rail)
        elif on_h and on_v:
            # If a marker lies on both, choose the axis with more distinct
            # rails in its family as the set of targets.
            if len(horizontal) > len(vertical):
                line(r, c, True)
                for rail in vertical:
                    if rail != c:
                        flare(r, rail)
            else:
                line(r, c, False)
                for rail in vertical:
                    if rail != c:
                        flare(r, rail)
        else:
            # Fallback: project along the long dimension.
            line(r, c, h >= w)

    return out

